// Stryker Trading Academy: /demo-curriculum (unlisted preview page)
//
// Behaviour for the four Curriculum-section bento variations on
// demo-curriculum.html (markup generated by tools/demo-curriculum/gen.py).
//
//   switcher  sticky A/B/C/D chips; the chip of the variation in view lights up
//   A tracks  "All N chapters" toggles open the full list inside its tile
//             (aria-expanded); spotlight on fine pointers
//   B journey the stage tile nearest the reading line becomes active and its
//             node on the path lights up; a runner dot travels the route
//             (one rAF loop, only while B is on screen)
//   C mosaic  tap/Enter flips a card to its summary (aria-pressed); collapsed
//             to the first cards until "Show all" is pressed
//   D stats   numbers count up once when first seen
//
// Motion: transforms/opacity only; loops stop off-screen (.dp-off also freezes
// CSS loops there). prefers-reduced-motion: no runner, no count-up, instant
// flips (cross-fade instead of 3D turn).
//
// Depends on: nothing (style.css tokens, demo-curriculum.css).

(function () {
  'use strict';
  var $ = function (s, r) { return (r || document).querySelector(s); };
  var $$ = function (s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); };
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var fine = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
  var root = document.documentElement;

  // ------------------------------------------------------------ theme toggle
  var tb = $('#dp-theme');
  if (tb) tb.addEventListener('click', function () {
    var toDay = root.getAttribute('data-theme') !== 'light';
    if (toDay) root.setAttribute('data-theme', 'light'); else root.removeAttribute('data-theme');
    try { localStorage.setItem('stryker_theme', toDay ? 'day' : 'night'); } catch (e) {}
  });

  // ------------------------------------------- visibility of each variation
  var vars = $$('.dp-var');
  var visible = {};
  var chips = $$('.dp-chips a');
  function lightChip() {
    var line = window.innerHeight * 0.33, pick = null;
    vars.forEach(function (v) {
      var r = v.getBoundingClientRect();
      if (r.top <= line && r.bottom > line) pick = v.id.slice(4);
    });
    if (!pick) pick = 'A';
    chips.forEach(function (c) { c.classList.toggle('on', c.getAttribute('data-v') === pick); });
  }
  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function (es) {
      es.forEach(function (en) {
        visible[en.target.id] = en.isIntersecting;
        en.target.classList.toggle('dp-off', !en.isIntersecting);
        if (en.target.id === 'var-B') runnerWake();
      });
    }, { rootMargin: '80px 0px' });
    vars.forEach(function (v) { io.observe(v); });
  } else {
    vars.forEach(function (v) { visible[v.id] = true; });
  }

  var scrollQueued = false;
  function onScroll() {
    if (scrollQueued) return;
    scrollQueued = true;
    requestAnimationFrame(function () {
      scrollQueued = false;
      lightChip();
      if (visible['var-B'] !== false) stageStep();
    });
  }
  window.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', onScroll);

  // spotlight that follows the pointer (desktop only)
  if (fine && !reduced) {
    $$('.ca-tile, .cb-tile, .cd-tile').forEach(function (t) {
      t.addEventListener('pointermove', function (e) {
        var r = t.getBoundingClientRect();
        t.style.setProperty('--mx', (e.clientX - r.left) + 'px');
        t.style.setProperty('--my', (e.clientY - r.top) + 'px');
      });
    });
  }

  // ================================================================ A tracks
  $$('.ca-more').forEach(function (b) {
    var list = document.getElementById(b.getAttribute('aria-controls'));
    var lbl = b.querySelector('span'), base = lbl.textContent;
    b.addEventListener('click', function () {
      var open = b.getAttribute('aria-expanded') !== 'true';
      b.setAttribute('aria-expanded', String(open));
      list.hidden = !open;
      lbl.textContent = open ? 'Show less' : base;
      if (open && !reduced) { list.classList.remove('enter'); void list.offsetWidth; list.classList.add('enter'); }
    });
  });

  // ================================================================ B journey
  var stages = $$('.cb-stage');
  var nodeSets = $$('.cb-line').map(function (svg) { return $$('.cb-node', svg); });
  var curStage = -1;
  function setStage(i) {
    if (i === curStage) return;
    curStage = i;
    stages.forEach(function (s, k) { s.classList.toggle('on', k === i); });
    nodeSets.forEach(function (ns) { ns.forEach(function (n, k) { n.classList.toggle('on', k <= i); }); });
  }
  function stageStep() {
    if (!stages.length) return;
    var line = window.innerHeight * 0.5, best = -1, bestD = Infinity;
    stages.forEach(function (s, k) {
      var r = s.getBoundingClientRect();
      if (r.bottom < 0 || r.top > window.innerHeight) return;
      var d = Math.abs((r.top + r.bottom) / 2 - line);
      if (d < bestD) { bestD = d; best = k; }
    });
    if (best >= 0) setStage(best);
  }
  stages.forEach(function (s, k) {
    s.addEventListener('mouseenter', function () { setStage(k); });
    s.addEventListener('focus', function () { setStage(k); });
  });

  // runner dot travels the visible route; one rAF loop, only while B is on screen
  var runRaf = 0, t0 = 0;
  function activeRoute() {
    var lines = $$('.cb-line');
    for (var i = 0; i < lines.length; i++) if (lines[i].getBoundingClientRect().width > 0) return lines[i];
    return null;
  }
  function runnerFrame(t) {
    runRaf = 0;
    if (visible['var-B'] === false || reduced || document.hidden) return;
    var svg = activeRoute();
    if (svg) {
      var p = svg.querySelector('.cb-route'), dot = svg.querySelector('.cb-runner');
      if (p && dot && p.getTotalLength) {
        if (!t0) t0 = t;
        var L = p.getTotalLength(), u = ((t - t0) / 7000) % 1;
        var e = u < 0.85 ? u / 0.85 : 1;            // travel, then rest at chapter 64
        var e2 = e < .5 ? 2 * e * e : 1 - Math.pow(-2 * e + 2, 2) / 2;
        var pt = p.getPointAtLength(L * e2);
        dot.setAttribute('transform', 'translate(' + pt.x.toFixed(1) + ' ' + pt.y.toFixed(1) + ')');
        dot.style.opacity = u > 0.97 ? String((1 - u) / 0.03) : '1';
      }
    }
    runRaf = requestAnimationFrame(runnerFrame);
  }
  function runnerWake() {
    if (!runRaf && !reduced && visible['var-B'] !== false) runRaf = requestAnimationFrame(runnerFrame);
  }
  document.addEventListener('visibilitychange', runnerWake);

  // ================================================================ C mosaic
  var mosaic = $('#cc-mosaic'), more = $('.cc-more');
  if (mosaic && more) {
    mosaic.classList.add('is-collapsed');
    more.addEventListener('click', function () {
      var open = mosaic.classList.contains('is-collapsed');
      mosaic.classList.toggle('is-collapsed', !open);
      more.setAttribute('aria-expanded', String(open));
      more.textContent = open ? 'Show fewer' : more.getAttribute('data-label');
    });
    more.setAttribute('data-label', more.textContent);
  }
  $$('.cc-card').forEach(function (c) {
    c.addEventListener('click', function () {
      c.setAttribute('aria-pressed', c.getAttribute('aria-pressed') === 'true' ? 'false' : 'true');
    });
  });

  // ============================================================ count-ups (A, D)
  var counted = $$('[data-count]');
  if (!reduced && 'IntersectionObserver' in window) {
    var cio = new IntersectionObserver(function (es) {
      es.forEach(function (en) {
        if (!en.isIntersecting) return;
        cio.unobserve(en.target);
        var el = en.target, to = +el.getAttribute('data-count'), start = 0;
        function f(t) {
          if (!start) start = t;
          var k = Math.min(1, (t - start) / 900);
          el.textContent = String(Math.round(to * (1 - Math.pow(1 - k, 3))));
          if (k < 1) requestAnimationFrame(f);
        }
        requestAnimationFrame(f);
      });
    }, { threshold: 0.6 });
    counted.forEach(function (el) { cio.observe(el); });
  }

  lightChip();
  stageStep();
})();
